package android.text;
public final class TextUtils {public static boolean isEmpty(CharSequence s){return s==null||s.length()==0;}public static boolean equals(CharSequence a,CharSequence b){return a==b||(a!=null&&b!=null&&a.toString().contentEquals(b));}public static String join(CharSequence sep,Iterable<?> items){StringBuilder out=new StringBuilder();for(Object x:items){if(out.length()>0)out.append(sep);out.append(x);}return out.toString();}public static String join(CharSequence sep,Object[] items){return join(sep,java.util.Arrays.asList(items));}public static boolean isDigitsOnly(CharSequence s){for(int i=0;i<s.length();i++)if(!Character.isDigit(s.charAt(i)))return false;return true;}public static String[] split(String s,String regex){return s.isEmpty()?new String[0]:s.split(regex,-1);}
    public enum TruncateAt {START,MIDDLE,END,MARQUEE}
}
